    def _safe_mutex_name(self, mutex: str) -> str:
        """Convert a mutex expression (possibly 'locks[0]') to a valid WhyML identifier."""
        return self._whyml_ident(mutex.replace("[", "_").replace("]", "").replace(".", "_"))
